@inject InventoryAlertService AlertService
@implements IDisposable

<span class="badge @BadgeClass">@AlertService.CurrentLowStockCount</span>

@code {
    private string BadgeClass => AlertService.CurrentLowStockCount > 0 ? "bg-danger" : "bg-secondary";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
    }

    private Task HandleAlertCountChanged()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
