@page "/dashboard"
@rendermode InteractiveServer
@using sv_fa06e7e277134fef95efc22d234515ad.Services
@using sv_fa06e7e277134fef95efc22d234515ad.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted mb-4">@WarehouseState.CurrentWarehouseName</h4>

<div class="row">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted small">Items below minimum level</p>
                <p class="text-muted small">Auto-refreshes every 10 seconds</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseName</p>
                <p class="text-muted small">Switch warehouses using the top bar selector</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="text-muted small">Polling stops when you leave this page</p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        AlertService.StartPolling();
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private Task HandleAlertCountChanged()
    {
        return InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        AlertService.StopPolling();
    }
}

